#include "semantic.h"
#include <stdlib.h>
#include <string.h>
typedef struct Symbol{char*name;struct Symbol*next;}Symbol;typedef struct Scope{Symbol*symbols;struct Scope*parent;}Scope;
static int errors;static Scope*push(Scope*p){Scope*s=calloc(1,sizeof(*s));s->parent=p;return s;}static void pop(Scope*s){Symbol*x=s->symbols;while(x){Symbol*y=x->next;free(x->name);free(x);x=y;}free(s);}static int has(Scope*s,const char*n){for(;s;s=s->parent)for(Symbol*x=s->symbols;x;x=x->next)if(!strcmp(x->name,n))return 1;return 0;}static int local(Scope*s,const char*n){for(Symbol*x=s->symbols;x;x=x->next)if(!strcmp(x->name,n))return 1;return 0;}static void declare(Scope*s,const char*n,int line,FILE*f){if(local(s,n)){fprintf(f,"line %d: redeclaration of '%s'\n",line,n);errors++;return;}Symbol*x=calloc(1,sizeof(*x));size_t len=strlen(n)+1;x->name=malloc(len);if(x->name)memcpy(x->name,n,len);x->next=s->symbols;s->symbols=x;}
static void expr(const AstNode*n,Scope*s,FILE*f){if(!n)return;switch(n->kind){case AST_IDENT:if(!has(s,n->data.ident.name)){fprintf(f,"line %d: use of undeclared identifier '%s'\n",n->line,n->data.ident.name);errors++;}break;case AST_ASSIGN:if(!has(s,n->data.assign.name)){fprintf(f,"line %d: assignment to undeclared identifier '%s'\n",n->line,n->data.assign.name);errors++;}expr(n->data.assign.value,s,f);break;case AST_BINARY:expr(n->data.binary.left,s,f);expr(n->data.binary.right,s,f);break;case AST_UNARY:expr(n->data.unary.operand,s,f);break;default:break;}}
static void walk(const AstNode*n,Scope*s,FILE*f){for(;n;n=n->next){switch(n->kind){case AST_BLOCK:{Scope*x=push(s);walk(n->data.block.items,x,f);pop(x);break;}case AST_DECL:declare(s,n->data.decl.name,n->line,f);expr(n->data.decl.initializer,s,f);break;case AST_ASSIGN:if(!has(s,n->data.assign.name)){fprintf(f,"line %d: assignment to undeclared identifier '%s'\n",n->line,n->data.assign.name);errors++;}expr(n->data.assign.value,s,f);break;case AST_EXPR_STMT:expr(n->data.expr_stmt.expr,s,f);break;case AST_FOR:{Scope*x=push(s);walk(n->data.for_loop.init,x,f);expr(n->data.for_loop.condition,x,f);walk(n->data.for_loop.update,x,f);walk(n->data.for_loop.body,x,f);pop(x);break;}case AST_WHILE:case AST_DO_WHILE:expr(n->data.loop.condition,s,f);walk(n->data.loop.body,s,f);break;default:expr(n,s,f);break;}}}
int semantic_check(const AstNode*root,FILE*f){errors=0;Scope*s=push(NULL);walk(root,s,f);pop(s);return errors?1:0;}
